package br.com.erp;
import com.fasterxml.jackson.databind.JsonNode;
import java.math.BigDecimal;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.put;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
class PosCommercialTest extends SaleFixture {
 String manager;UUID managerId;
 @BeforeEach void manager()throws Exception{var u=postApi("/api/v1/users",auth,Map.of("name","Gestor","email","manager@example.com","password",password,"permissions",List.of("pos:read","treasury:read","pos:discount-approve")),201);managerId=UUID.fromString(u.get("id").asText());manager=postApi("/api/v1/auth/login",null,Map.of("company",company,"email","manager@example.com","password",password),200).get("token").asText();}
 Map<String,Object> discounted(String qty,String amount){return Map.of("productId",product,"quantity",qty,"expectedUnitPrice","10.25","discountAmount",amount);}
 Map<String,Object> checkout(UUID key,String qty,String discount){return Map.of("requestId",key,"sessionId",session,"tendered","100","items",List.of(discounted(qty,discount)));}
 Map<String,Object> cart(UUID key,String qty,String discount){return Map.of("requestId",key,"sessionId",session,"note","Carrinho informado para revisão","items",List.of(discounted(qty,discount)));}
 JsonNode policy(String percent,long version,int expected)throws Exception{var r=http.perform(put("/api/v1/pos/discount-policies/"+branch).header("Authorization","Bearer "+auth).contentType("application/json").content(json.writeValueAsString(Map.of("version",version,"operatorPercent",percent)))).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().is(expected)).andReturn();return json.readTree(r.getResponse().getContentAsString());}
 JsonNode request(String discount)throws Exception{return postApi("/api/v1/pos/discount-requests",auth,cart(UUID.randomUUID(),"2",discount),201);}
 Map<String,Object> decision(UUID key,boolean approve,long version){return Map.of("requestId",key,"version",version,"approve",approve,"note","Decisão conferida pelo gestor");}
 JsonNode approve(JsonNode request)throws Exception{return postApi("/api/v1/pos/discount-requests/"+request.get("id").asText()+"/decision",manager,decision(UUID.randomUUID(),true,0),200);}
 JsonNode suspend()throws Exception{return postApi("/api/v1/pos/suspensions",auth,cart(UUID.randomUUID(),"2","0"),201);}
 Map<String,Object> fromSuspension(JsonNode draft,UUID key){var body=new HashMap<>(checkout(key,"2","0"));body.put("suspensionId",draft.get("id").asText());body.put("suspensionVersion",draft.get("version").asLong());return body;}
 JsonNode saved(JsonNode draft,String qty,String discount,int expected)throws Exception{var body=new HashMap<>(cart(UUID.randomUUID(),qty,discount));body.put("version",draft.get("version").asLong());var r=http.perform(put("/api/v1/pos/suspensions/"+draft.get("id").asText()).header("Authorization","Bearer "+auth).contentType("application/json").content(json.writeValueAsString(body))).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().is(expected)).andReturn();return json.readTree(r.getResponse().getContentAsString());}
 @Test void defaultPolicyRejectsDiscountWithoutApprovalAndPolicyIsVersioned()throws Exception{money("0",getApi("/api/v1/pos/discount-policies/"+branch,auth,200).get("operatorPercent"));sell(checkout(UUID.randomUUID(),"2","1"),403);money("10",policy("10",0,200).get("operatorPercent"));policy("20",0,409);policy("100.01",1,400);var s=sell(checkout(UUID.randomUUID(),"2","2.05"),201);money("20.50",s.get("grossTotal"));money("2.05",s.get("discountTotal"));money("18.45",s.get("total"));money("2.05",s.get("items").get(0).get("discountAmount"));assertEquals(0,new BigDecimal("18.45").compareTo(balance()));}
 @Test void limitsArePerItemAndPermissionToDiscountIsIndependent()throws Exception{policy("10",0,200);sell(checkout(UUID.randomUUID(),"2","2.06"),403);db.update("DELETE FROM user_permission WHERE tenant_id=? AND permission='pos:discount'",tenant);sell(checkout(UUID.randomUUID(),"2","1"),403);sell(checkout(UUID.randomUUID(),"2","0"),201);}
 @Test void discountBoundsAndZeroNetSaleAreRejected()throws Exception{policy("100",0,200);sell(checkout(UUID.randomUUID(),"2","20.51"),400);sell(checkout(UUID.randomUUID(),"2","20.50"),400);sell(checkout(UUID.randomUUID(),"2","-0.01"),400);assertEquals(0,count("pos_sale"));}
 @Test void requesterCannotApproveOwnRequestAndDifferentManagerCanApprove()throws Exception{var request=request("5");postApi("/api/v1/pos/discount-requests/"+request.get("id").asText()+"/decision",auth,decision(UUID.randomUUID(),true,0),403);var approved=approve(request);assertEquals("APPROVED",approved.get("status").asText());var body=new HashMap<>(checkout(UUID.randomUUID(),"2","5"));body.put("discountApprovalId",approved.get("id").asText());var sale=sell(body,201);money("15.50",sale.get("total"));assertEquals("CONSUMED",getApi("/api/v1/pos/discount-requests/"+request.get("id").asText(),auth,200).get("status").asText());assertEquals(sale,sell(body,201));body.put("requestId",UUID.randomUUID());sell(body,409);}
 @Test void approvalCannotAuthorizeChangedCartOrPolicyAndCanExpire()throws Exception{var r=approve(request("5"));var body=new HashMap<>(checkout(UUID.randomUUID(),"2","4"));body.put("discountApprovalId",r.get("id").asText());sell(body,409);body.put("items",List.of(discounted("2","5")));policy("1",0,200);sell(body,409);var r2=approve(request("5"));body.put("discountApprovalId",r2.get("id").asText());db.update("UPDATE pos_discount_request SET expires_at=? WHERE tenant_id=? AND id=?",java.time.OffsetDateTime.now(java.time.ZoneOffset.UTC).minusMinutes(1),tenant,UUID.fromString(r2.get("id").asText()));sell(body,409);assertEquals(0,count("pos_sale"));}
 @Test void approvalRevalidatesManagerPermissionAndBranchAccess()throws Exception{var r=approve(request("5"));var body=new HashMap<>(checkout(UUID.randomUUID(),"2","5"));body.put("discountApprovalId",r.get("id").asText());db.update("DELETE FROM user_permission WHERE tenant_id=? AND user_id=? AND permission='pos:discount-approve'",tenant,managerId);sell(body,409);db.update("INSERT INTO user_permission(tenant_id,user_id,permission) VALUES(?,?,'pos:discount-approve')",tenant,managerId);db.update("UPDATE app_user SET all_branches=FALSE WHERE tenant_id=? AND id=?",tenant,managerId);sell(body,409);}
 @Test void approvalRemainsAvailableWhenStockOrPaymentFails()throws Exception{var r=approve(request("5"));var body=new HashMap<>(checkout(UUID.randomUUID(),"2","5"));body.put("discountApprovalId",r.get("id").asText());db.update("UPDATE stock_balance SET quantity=1 WHERE tenant_id=? AND warehouse_id=? AND product_id=?",tenant,UUID.fromString(warehouse),UUID.fromString(product));sell(body,409);assertEquals("APPROVED",getApi("/api/v1/pos/discount-requests/"+r.get("id").asText(),auth,200).get("status").asText());assertEquals(0,count("pos_sale"));}
 @Test void decisionsAndRequestsAreIdempotentAndRejectionCannotBeUsed()throws Exception{var body=cart(UUID.randomUUID(),"2","5");var r=postApi("/api/v1/pos/discount-requests",auth,body,201);assertEquals(r,postApi("/api/v1/pos/discount-requests",auth,body,201));var d=decision(UUID.randomUUID(),false,0);String path="/api/v1/pos/discount-requests/"+r.get("id").asText()+"/decision";var rejected=postApi(path,manager,d,200);assertEquals(rejected,postApi(path,manager,d,200));postApi(path,manager,decision(UUID.randomUUID(),true,1),409);var sale=new HashMap<>(checkout(UUID.randomUUID(),"2","5"));sale.put("discountApprovalId",r.get("id").asText());sell(sale,409);}
 @Test void priceOrUnitChangeInvalidatesPendingApproval()throws Exception{var r=request("5");db.update("UPDATE product SET unit='UN' WHERE tenant_id=? AND id=?",tenant,UUID.fromString(product));postApi("/api/v1/pos/discount-requests/"+r.get("id").asText()+"/decision",manager,decision(UUID.randomUUID(),true,0),409);}
 @Test void returnsRefundDiscountedHistoricalTotalRatherThanGross()throws Exception{policy("100",0,200);var s=sell(checkout(UUID.randomUUID(),"2","2.50"),201);postApi("/api/v1/pos/sales/"+s.get("id").asText()+"/returns",auth,Map.of("requestId",UUID.randomUUID(),"sessionId",session,"version",0,"note","Devolução parcial conferida","externalRefundsConfirmed",false,"items",List.of(Map.of("productId",product,"quantity","1")),"refunds",List.of(Map.of("paymentId",s.get("payments").get(0).get("id").asText(),"amount","9","reference",""))),201);assertEquals(0,new BigDecimal("9").compareTo(balance()));}
 @Test void suspensionPersistsSnapshotWithoutReservingStockOrMovingCash()throws Exception{var body=cart(UUID.randomUUID(),"2","0");var draft=postApi("/api/v1/pos/suspensions",auth,body,201);assertEquals(draft,postApi("/api/v1/pos/suspensions",auth,body,201));money("20.50",draft.get("total"));assertEquals(0,BigDecimal.TEN.compareTo(quantity(product)));assertEquals(0,count("treasury_operation"));assertEquals(1,count("stock_operation"));assertEquals(0,getApi("/api/v1/pos/cash-sessions/"+session,auth,200).get("version").asInt());}
 @Test void suspensionFinishesOnceAndRetryReturnsOriginalSale()throws Exception{var d=suspend();var body=fromSuspension(d,UUID.randomUUID());var sale=sell(body,201);assertEquals(sale,sell(body,201));assertEquals("COMPLETED",getApi("/api/v1/pos/suspensions/"+d.get("id").asText(),auth,200).get("status").asText());body.put("requestId",UUID.randomUUID());sell(body,409);assertEquals(1,count("pos_sale"));}
 @Test void editingResumedCartRequiresVersionedSaveBeforeCheckout()throws Exception{var d=suspend();var body=fromSuspension(d,UUID.randomUUID());body.put("items",List.of(discounted("3","0")));sell(body,409);var updated=saved(d,"3","0",200);saved(d,"4","0",409);body.put("suspensionVersion",updated.get("version").asLong());sell(body,201);assertEquals(0,new BigDecimal("7").compareTo(quantity(product)));}
 @Test void suspensionCanResumeInNewShiftAndRechecksStockAndPrice()throws Exception{var d=suspend();postApi("/api/v1/pos/cash-sessions/"+session+"/close",auth,Map.of("requestId",UUID.randomUUID(),"version",0,"countedAmount","0","note","Fechamento do turno"),200);session=postApi("/api/v1/pos/cash-sessions",auth,Map.of("requestId",UUID.randomUUID(),"terminalId",terminal,"openingAmount","0","note","Novo turno de teste"),201).get("id").asText();db.update("UPDATE product SET sale_price=11 WHERE tenant_id=? AND id=?",tenant,UUID.fromString(product));sell(fromSuspension(d,UUID.randomUUID()),409);db.update("UPDATE product SET sale_price=10.25 WHERE tenant_id=? AND id=?",tenant,UUID.fromString(product));db.update("UPDATE stock_balance SET quantity=1 WHERE tenant_id=? AND warehouse_id=? AND product_id=?",tenant,UUID.fromString(warehouse),UUID.fromString(product));sell(fromSuspension(d,UUID.randomUUID()),409);assertEquals("SUSPENDED",getApi("/api/v1/pos/suspensions/"+d.get("id").asText(),auth,200).get("status").asText());}
 @Test void discardedSuspensionCannotBeFinalizedAndDiscardReplayIsSafe()throws Exception{var d=suspend();String path="/api/v1/pos/suspensions/"+d.get("id").asText()+"/discard";var body=Map.of("requestId",UUID.randomUUID(),"version",0,"note","Carrinho abandonado");var discarded=postApi(path,auth,body,200);assertEquals(discarded,postApi(path,auth,body,200));sell(fromSuspension(d,UUID.randomUUID()),409);assertEquals(0,count("pos_sale"));}
 @Test void suspensionSavingDiscountDoesNotApproveIt()throws Exception{var d=postApi("/api/v1/pos/suspensions",auth,cart(UUID.randomUUID(),"2","5"),201);var body=fromSuspension(d,UUID.randomUUID());body.put("items",List.of(discounted("2","5")));sell(body,403);var r=approve(request("5"));body.put("discountApprovalId",r.get("id").asText());sell(body,201);}
 @Test void permissionsAndScopeProtectDraftsPoliciesAndApprovalLists()throws Exception{var d=suspend();var r=request("5");assertEquals(1,getApi("/api/v1/pos/discount-requests",manager,200).get("total").asInt());assertEquals(0,getApi("/api/v1/pos/suspensions",manager,200).get("total").asInt());getApi("/api/v1/pos/suspensions/"+d.get("id").asText(),manager,404);db.update("DELETE FROM user_permission WHERE tenant_id=? AND permission='pos:suspend'",tenant);postApi("/api/v1/pos/suspensions",auth,cart(UUID.randomUUID(),"2","0"),403);String other="other-"+UUID.randomUUID();provisioning.create("Outra",other,"Admin","admin@example.com",password);getApi("/api/v1/pos/discount-requests/"+r.get("id").asText(),token(other),404);db.update("UPDATE app_user SET all_branches=FALSE WHERE tenant_id=?",tenant);assertEquals(0,getApi("/api/v1/pos/suspensions",auth,200).get("total").asInt());getApi("/api/v1/pos/discount-policies/"+branch,auth,404);}
 @Test void perItemCapCannotBeHiddenByAnotherExpensiveItem()throws Exception{policy("10",0,200);String expensive=createProduct("EXPENSIVE","1000");stock(expensive,"1");var body=new HashMap<>(checkout(UUID.randomUUID(),"1","10.25"));body.put("items",List.of(discounted("1","10.25"),item(expensive,"1","1000")));body.put("tendered","2000");sell(body,403);assertEquals(0,count("pos_sale"));}
 @Test void zeroDiscountRetainsLegacyRequestFingerprint()throws Exception{UUID key=UUID.randomUUID();var original=sell(input(key,"2","10.25","100"),201);assertEquals(original,sell(checkout(key,"2","0.00"),201));}
 @Test void updateRetryAfterCompletionCannotReactivateDraft()throws Exception{var d=suspend();var update=new HashMap<>(cart(UUID.randomUUID(),"3","0"));update.put("version",0);String path="/api/v1/pos/suspensions/"+d.get("id").asText();var r=http.perform(put(path).header("Authorization","Bearer "+auth).contentType("application/json").content(json.writeValueAsString(update))).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isOk()).andReturn();var saved=json.readTree(r.getResponse().getContentAsString());var body=fromSuspension(saved,UUID.randomUUID());body.put("items",List.of(discounted("3","0")));sell(body,201);var replay=http.perform(put(path).header("Authorization","Bearer "+auth).contentType("application/json").content(json.writeValueAsString(update))).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isOk()).andReturn();assertEquals("COMPLETED",json.readTree(replay.getResponse().getContentAsString()).get("status").asText());assertEquals(1,count("pos_sale"));assertEquals(0,new BigDecimal("7").compareTo(quantity(product)));}
 @Test void concurrentUseOfApprovalConsumesExactlyOnce()throws Exception{var a=approve(request("5"));var first=new HashMap<>(checkout(UUID.randomUUID(),"2","5"));first.put("discountApprovalId",a.get("id").asText());var second=new HashMap<>(first);second.put("requestId",UUID.randomUUID());assertEquals(List.of(201,409),race(first,second));assertEquals(1,count("pos_sale"));assertEquals(1,count("treasury_operation"));}
 @Test void approverCannotBorrowAnotherOperatorsApprovalEvenAsSupervisor()throws Exception{var a=approve(request("5"));for(String p:List.of("pos:sell","pos:discount","pos:supervise","treasury:move"))db.update("INSERT INTO user_permission(tenant_id,user_id,permission) VALUES(?,?,?)",tenant,managerId,p);var body=new HashMap<>(checkout(UUID.randomUUID(),"2","5"));body.put("discountApprovalId",a.get("id").asText());postApi("/api/v1/pos/sales",manager,body,409);assertEquals(0,count("pos_sale"));}
 @Test void policyWriteRequiresItsOwnPermission()throws Exception{http.perform(put("/api/v1/pos/discount-policies/"+branch).header("Authorization","Bearer "+manager).contentType("application/json").content(json.writeValueAsString(Map.of("version",0,"operatorPercent","100")))).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isForbidden());}
 @Test void checkoutRaceWithDiscardHasOnlyOneOutcome()throws Exception{var d=suspend();var sale=fromSuspension(d,UUID.randomUUID());String path="/api/v1/pos/suspensions/"+d.get("id").asText()+"/discard";try(var pool=Executors.newFixedThreadPool(2)){var gate=new CountDownLatch(1);var a=pool.submit(()->{gate.await();return status("/api/v1/pos/sales",sale);});var b=pool.submit(()->{gate.await();return status(path,Map.of("requestId",UUID.randomUUID(),"version",0,"note","Descarte concorrente"));});gate.countDown();var result=new ArrayList<>(List.of(a.get(30,TimeUnit.SECONDS),b.get(30,TimeUnit.SECONDS)));Collections.sort(result);assertTrue(result.equals(List.of(200,409))||result.equals(List.of(201,409)));}var current=getApi("/api/v1/pos/suspensions/"+d.get("id").asText(),auth,200);assertEquals(current.get("status").asText().equals("COMPLETED")?1:0,count("pos_sale"));}
 @Test void concurrentCheckoutOfSameSuspensionHasSingleEffect()throws Exception{var d=suspend();assertEquals(List.of(201,409),race(fromSuspension(d,UUID.randomUUID()),fromSuspension(d,UUID.randomUUID())));assertEquals(1,count("pos_sale"));assertEquals(0,new BigDecimal("8").compareTo(quantity(product)));}
}
